"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Policy:
    max_size: int | None = None
    max_age: int | None = None  # seconds
    naming: str = "numbered"
    offset: int = 0  # seconds east of UTC
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


class _Bad(Exception):
    pass


def _size(v):
    m = re.fullmatch(r"([0-9]+)([KkMmGg]?)", v)
    if not m:
        raise _Bad(v)
    return int(m[1]) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m[2].lower()]


def _duration(v):
    m = re.fullmatch(r"([0-9]+)([mhd])", v)
    if not m:
        raise _Bad(v)
    return int(m[1]) * {"m": 60, "h": 3600, "d": 86400}[m[2]]


def _off_or(f):
    return lambda v: None if v == "off" else f(v)


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _Bad(v)
    return v


def _offset(v):
    m = re.fullmatch(r"([+-])([0-9]{2}):([0-9]{2})", v)
    if not m or int(m[2]) > 23 or int(m[3]) > 59:
        raise _Bad(v)
    s = int(m[2]) * 3600 + int(m[3]) * 60
    return -s if m[1] == "-" else s


def _number(minimum):
    def f(v):
        if not re.fullmatch(r"[0-9]+", v) or int(v) < minimum:
            raise _Bad(v)
        return int(v)

    return f


_KEYS = {
    "max_size": _off_or(_size),
    "max_age": _off_or(_duration),
    "naming": _naming,
    "offset": _offset,
    "compress_after": _number(0),
    "keep": _number(1),
    "keep_days": _off_or(_number(1)),
}


def load(path: Path):
    """Returns (defaults, {stream name: Policy}); the dict holds the streams with a section."""
    if not path.exists():
        return Policy(), {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    sections: dict[str, dict] = {}
    current = None
    try:
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line[0] in "#;":
                continue
            if line[0] == "[":
                if not line.endswith("]"):
                    raise _Bad(line)
                title = line[1:-1]
                if title == "defaults":
                    key = "defaults"
                elif title.startswith("stream ") and streams.valid(title[7:]):
                    key = title
                else:
                    raise _Bad(line)
                if key in sections:
                    raise _Bad(f"section given twice: {title}")
                sections[key] = current = {}
                continue
            if current is None or "=" not in line:
                raise _Bad(line)
            k, v = (s.strip() for s in line.split("=", 1))
            if k not in _KEYS or k in current:
                raise _Bad(line)
            current[k] = _KEYS[k](v)
    except _Bad as e:
        raise DataError("policy", f"{path.name}: invalid: {e}") from None
    defaults = replace(Policy(), **sections.get("defaults", {}))
    per = {k[7:]: replace(defaults, **v) for k, v in sections.items() if k != "defaults"}
    return defaults, per
