"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})")
_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}")
_DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?")


def parse_time(text):
    """A time of data.md, section 2 (the legacy form is UTC); None when it is not one."""
    if not isinstance(text, str):
        return None
    try:
        if _TIME.fullmatch(text):
            t = datetime.fromisoformat(text)
        elif _LEGACY.fullmatch(text):
            t = datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        else:
            return None
    except ValueError:
        return None
    return t


class Archive:
    def __init__(self, name, key, gz):
        self.name, self.key, self.gz = name, key, gz
        self.new = False
        self.final = name
        self.compress = False
        self.time = None  # the string in state.json
        self.remove = False


def _archives(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    prefix = f"{name}.log."
    found = {}
    if d.is_dir():
        for p in d.iterdir():
            n = p.name
            if not n.startswith(prefix) or not p.is_file():
                continue
            rest, gz = (n[len(prefix):-3], True) if n.endswith(".gz") else (n[len(prefix):], False)
            if naming == "numbered":
                if not re.fullmatch(r"[1-9][0-9]*", rest):
                    continue
                key = (int(rest),)
            else:
                m = _DAY.fullmatch(rest)
                if not m:
                    continue
                try:
                    day = date.fromisoformat(m[1])
                except ValueError:
                    continue
                key = (day, int(m[2] or 1))
            if key in found:
                raise DataError("archives", f"{name}: two archives in the same place")
            found[key] = Archive(n, key, gz)
    return found


def _first_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
        text = line.decode("utf-8").rstrip("\n").split(" ", 1)[0]
    except (OSError, UnicodeDecodeError):
        return None
    return parse_time(text) if _TIME.fullmatch(text) else None


def _check_state(doc, names):
    for name in names:
        entry = doc["streams"].get(name)
        if entry is None:
            continue
        bad = None
        if "opened" in entry and parse_time(entry["opened"]) is None:
            bad = "opened"
        arch = entry.get("archives", {})
        if not isinstance(arch, dict):
            bad = "archives"
        elif any(parse_time(v) is None for v in arch.values()):
            bad = "archives"
        r = entry.get("rotations", 0)
        if not isinstance(r, int) or isinstance(r, bool) or r < 0:
            bad = "rotations"
        if bad:
            raise DataError("state", f"entry {name}: bad {bad}")


def run(ctx, wanted, dry_run, force):
    defaults, per = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = sorted(set(streams.active(ctx.data)) | set(per))
    _check_state(doc, existing)
    wanted = sorted(set(wanted))
    for w in wanted:
        if w not in existing:
            raise Refused("unknown-stream", f"no stream {w}")
    todo = wanted if wanted else existing
    now = ctx.now

    plans = []
    for name in todo:
        pol = per.get(name, defaults)
        entry = doc["streams"].get(name, {})
        arch = _archives(ctx, name, pol.naming)
        plans.append((name, pol, entry, arch))

    out = []
    n_rot = n_rem = n_comp = 0
    actions = []  # (stream, list of archives in age order, rotated?, log path)
    new_entries = {}
    for name, pol, entry, found in plans:
        log = streams.log_path(ctx.data, name)
        rotated = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, rotated = "rotate (forced)", "forced"
            elif pol.max_size is not None and size >= pol.max_size:
                what, rotated = "rotate (size)", "size"
            else:
                what = "not due"
                if pol.max_age is not None:
                    opened = parse_time(entry["opened"]) if "opened" in entry else _first_time(log)
                    if opened is not None and (now - opened).total_seconds() >= pol.max_age:
                        what, rotated = "rotate (age)", "age"
        times = entry.get("archives", {})
        archives = list(found.values())
        for a in archives:
            a.time = times.get(a.name)
        if rotated:
            if pol.naming == "numbered":
                key = (0,)
            else:
                day = now.astimezone(timezone(timedelta(seconds=pol.offset))).date()
                ks = [a.key[1] for a in archives if a.key[0] == day]
                key = (day, max(ks) + 1 if ks else 1)
            nname = f"{name}.log." + (
                str(key[0]) if pol.naming == "numbered" else key[0].isoformat() + (f".{key[1]}" if key[1] > 1 else ""))
            new = Archive(nname, key, False)
            new.new, new.time = True, dates.stamp(now)
            archives.append(new)
        archives.sort(key=lambda a: a.key)
        for pos, a in enumerate(archives, 1):
            t = parse_time(a.time) if a.time is not None else None
            if pos > pol.keep or (pol.keep_days is not None and t is not None
                                  and (now - t).total_seconds() >= pol.keep_days * 86400):
                a.remove = True
        kept = [a for a in archives if not a.remove]
        for i, a in enumerate(kept, 1):
            a.compress = i > pol.compress_after and not a.gz
            base = f"{name}.log.{i}" if pol.naming == "numbered" else a.name[:-3] if a.gz else a.name
            if pol.naming == "numbered" and not a.new:
                pass
            a.final = base + (".gz" if a.gz or a.compress else "")
        if rotated:
            n_rot += 1
        out.append(f"{name}: {what}")
        for a in kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.name}")
        for a in archives:
            if a.remove and not a.new:
                out.append(f"  remove {a.name}")
        n_rem += sum(1 for a in archives if a.remove and not a.new)
        n_comp += sum(1 for a in kept if a.compress)
        ne = {}
        if "opened" in entry or rotated:
            ne["opened"] = dates.stamp(now) if rotated else entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a.final: a.time for a in kept if a.time is not None}
        new_entries[name] = ne
        actions.append((archives, kept, rotated, log))
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")

    if dry_run:
        out.append("dry run: nothing written")
        return out

    for archives, kept, rotated, log in actions:
        d = log.parent
        for a in archives:
            if a.remove and not a.new:
                (d / a.name).unlink()
        tmp = {}
        if rotated:
            new = next(a for a in archives if a.new)
            if not new.remove:
                t = d / f".logkeep-{os.getpid()}-new-{log.name}"
                os.rename(log, t)
                log.write_bytes(b"")
                tmp[id(new)] = t
            else:
                log.write_bytes(b"")
        for i, a in enumerate(kept):
            if a.new:
                continue
            if a.final != a.name or a.compress:
                t = d / f".logkeep-{os.getpid()}-{log.name}-{i}"
                os.rename(d / a.name, t)
                tmp[id(a)] = t
        for a in kept:
            t = tmp.get(id(a))
            if t is None:
                continue
            if a.compress:
                (d / a.final).write_bytes(gzip.compress(t.read_bytes(), mtime=0))
                t.unlink()
            else:
                os.rename(t, d / a.final)
        if rotated and next(a for a in archives if a.new).remove:
            pass
    doc["streams"].update(new_entries)
    state.save(ctx.state_path, doc)
    return out
